<template><div class="page-shell"><div class="profile-grid"><section class="content-card"><h2>个人资料</h2><el-descriptions :column="1" border><el-descriptions-item label="用户名">{{user.username}}</el-descriptions-item><el-descriptions-item label="真实姓名">{{user.realName}}</el-descriptions-item><el-descriptions-item label="角色">{{user.role}}</el-descriptions-item><el-descriptions-item label="联系电话">{{user.phone||'-'}}</el-descriptions-item><el-descriptions-item label="电子邮箱">{{user.email||'-'}}</el-descriptions-item></el-descriptions></section><section class="content-card"><h2>修改密码</h2><el-form :model="form" label-width="90px"><el-form-item label="原密码"><el-input v-model="form.oldPassword" show-password/></el-form-item><el-form-item label="新密码"><el-input v-model="form.newPassword" show-password/></el-form-item><el-form-item label="确认密码"><el-input v-model="confirm" show-password/></el-form-item><el-form-item><el-button type="primary" @click="save">修改密码</el-button></el-form-item></el-form></section></div></div></template>
<script setup>import{reactive,ref}from'vue';import{ElMessage}from'element-plus';import http from'../api/http';import{getCurrentUser}from'../utils/auth';const user=getCurrentUser(),confirm=ref(''),form=reactive({userId:user.id,oldPassword:'',newPassword:''});const save=async()=>{if(form.newPassword!==confirm.value)return ElMessage.warning('两次输入的新密码不一致');await http.post('/users/update-password',form);ElMessage.success('密码修改成功');form.oldPassword='';form.newPassword='';confirm.value=''}</script>
<style scoped>.profile-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.content-card{margin-top:0}.content-card h2{margin:0 0 22px;color:#102a43}</style>
